pub async fn set_room(c: &mut Ctx) -> Result<(Membership, Room)> {
    let user_id = require_current_user(c)?.id;
    let Some(room_id) = c.param_str("room_id").and_then(integer_cast) else { return Err(Error::NotFound) };
    c.app()
