/// `reject_banned_ip`, unless the request is safe (GET/HEAD): 429 for a banned `remote_ip`.
pub async fn reject_banned_ip(c: &mut Ctx) -> Result<()> {
    if c.request.is_get() || c.request.is_head() {
        return Ok(());
    }
    let ip = c.request.remote_ip()?.to_string();
