pub fn ensure_can_administer(c: &mut Ctx) -> Result<()> {
    let allowed = current_user(c).is_some_and(|user| user.can_administer(None, false));
    if !allowed {
        return halt(head(StatusCode::FORBIDDEN));
    }
    Ok(())
}
