    let metadata = active_storage::analyzed_metadata(app, &blob).await?;
    app.write(move |tx| {
        let mut blob = blob;
        blob.update_metadata(tx.conn(), metadata).map_err(storage_error)?;
        touch_attachment_records(tx, blob.id)?;
        Ok(blob)
