fn request_id(incoming: Option<&str>) -> String {
    match incoming.filter(|id| !id.trim().is_empty()) {
        Some(id) => id.chars().filter(|c| c.is_alphanumeric() || *c == '_' || *c == '-' || *c == '@').take(255).collect(),
