/// `@account.update!(params.require(:account).permit(:name, :logo, settings: {}))`
pub async fn update(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    concerns::ensure_can_administer(c)?;
    let mut account = current_account(c).await?;

    let params = c.params.require("account")?.permit(&[Permit::from("name"), Permit::from("logo"), Permit::AnyHash("settings".into())]);
    let name = params.get("name").and_then(Param::to_s);
    let settings: Option<Vec<(String, String)>> = params
        .get("settings")
        .and_then(Param::as_hash)
        .map(|settings| settings.iter().map(|(key, value)| (key.clone(), value.to_s().unwrap_or_default())).collect());
    let logo = Assignment::from_params(&params, "logo")?.stage(c.app()).await?;

    let pending = c
        .app()
        .write(move |tx| {
            let settings: Option<Vec<(&str, &str)>> = settings.as_ref().map(|s| s.iter().map(|(k, v)| (k.as_str(), v.as_str())).collect());
            account.update(tx, name.as_deref(), None, settings.as_deref())?;
            attachments::assign(tx, Record::account(account.id), "logo", logo)
        })
        .await?;
    attachments::analyze_later(c.app(), pending);

    let location = c.url_for(&campfire_routes::edit_account());
    c.redirect_to_with(&location, Redirect { notice: Some("✓".into()), ..Redirect::default() })
}

/// `Current.account` where Rails dereferences it (a nil account raises NoMethodError).
pub async fn current_account(c: &Ctx) -> Result<Account> {
    c.app().read(Account::first).await?.ok_or_else(|| Error::internal(anyhow::anyhow!("no account")))
}
//! `Accounts::UsersController`: the people list's next pages, role changes and removal.

use askama::Template;
use campfire_db::{Role, User, UserChanges};
use campfire_kit::{Ctx, Error, Result, format};
use campfire_views::accounts;
use ruby_compat::integer_cast;

use crate::app::AppCtx;
use crate::concerns::{self, Before};
use crate::controllers::presenters;
use crate::controllers::presenters::pagination::Page;
use crate::controllers::presenters::view_context::Layout;

/// `set_page_and_extract_portion_from User.active.ordered, per_page: 500`,
/// rendered as `index.turbo_stream.erb` (the only template, so other formats are 406).
pub async fn index(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    c.respond_to(&[&format::TURBO_STREAM])?;
    let users = c.app().read_offloaded(User::active_ordered).await?;
    let page = Page::new(c.param_str("page"), users.len() as i64, &[500]);
    let secrets = c.app().secrets.clone();
    let users: Vec<_> = page.records(&users).iter().map(|user| presenters::user_summary(&secrets, user)).collect();
    let next_page = (!page.is_last()).then(|| page.next_param().to_string());

    let layout = Layout::load(c).await?;
    let html = layout.render(c, |ctx| accounts::UsersIndexTurboStream { ctx, users, next_page }.render())?;
    page.apply_headers(c);
    Ok(c.turbo_stream(html))
}

/// `@user.update(role: params.require(:user)[:role].presence_in(%w[ member administrator ]) || "member")`
pub async fn update(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    concerns::ensure_can_administer(c)?;
    let mut user = set_user(c).await?;
    let role = match c.params.require("user")?.get("role").and_then(|role| role.as_str()) {
        Some("administrator") => Role::Administrator,
        _ => Role::Member,
    };
    c.app().write(move |tx| user.update(tx, UserChanges { role: Some(role), ..UserChanges::default() })).await?;
    redirect_to_edit_account(c)
}

/// `@user.deactivate`
pub async fn destroy(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    concerns::ensure_can_administer(c)?;
    let mut user = set_user(c).await?;
    c.app().write(move |tx| user.deactivate(tx)).await?;
    redirect_to_edit_account(c)
}

/// `User.active.find(params[:user_id] || params[:id])`
async fn set_user(c: &Ctx) -> Result<User> {
    let id = c.param_str("user_id").or_else(|| c.param_str("id")).and_then(integer_cast).ok_or(Error::NotFound)?;
    c.app().read(move |conn| User::find_active(conn, id)).await
}

fn redirect_to_edit_account(c: &mut Ctx) -> Result {
    let location = c.url_for(&campfire_routes::edit_account());
    c.redirect_to(&location)
