+/// `authenticate_bot` (bots aren't in Rails Campfire as this app ports it): `Current.user` is the
+/// active bot whose key is `params[:bot_key]`, or the request is a 401.
+pub async fn authenticate_bot(c: &mut Ctx) -> Result<()> {
+    let key = c.param_str("bot_key").unwrap_or_default().to_string();
+    match c.app().read(move |conn| Bot::authenticate(conn, &key)).await? {
+        Some(bot) => {
+            c.set_current(CurrentUser(bot));
+            Ok(())
+        }
+        None => halt(head(StatusCode::UNAUTHORIZED)),
+    }
+}
